#include "../Source/PluginProcessor.h"
#include <iostream>
#include <stdexcept>
void check(bool b,const char* m){if(!b)throw std::runtime_error(m);}
void set(SpaceProcessor& p,const char* id,float v){auto* a=p.state.getParameter(id);a->setValueNotifyingHost(a->convertTo0to1(v));}
int main(){swell::Licence::unlockForTesting();try{juce::ScopedJuceInitialiser_GUI init;
for(double sr:{44100.,48000.,96000.})for(float width:{0.f,100.f}){SpaceProcessor p;set(p,"pingpong",1);set(p,"spaceOn",0);set(p,"focus",0);set(p,"delay",100);set(p,"feedback",60);set(p,"tw",width);p.prepareToPlay(sr,256);juce::AudioBuffer<float>b(2,256);juce::MidiBuffer m;double energy[3][2]{};for(int offset=0;offset<(int)(sr*1.7);offset+=256){b.clear();if(offset==0){b.setSample(0,0,.5f);b.setSample(1,0,.5f);}p.processBlock(b,m);if(offset==0)check(b.getSample(0,0)==.5f&&b.getSample(1,0)==.5f,"direct moved");for(int n=0;n<256;++n){int t=offset+n;for(int repeat=0;repeat<3;++repeat)if(t>=(int)(sr*.5*(repeat+1))&&t<(int)(sr*.5*(repeat+1)+sr*.03))for(int c=0;c<2;++c)energy[repeat][c]+=std::pow(b.getSample(c,n),2);}}for(int repeat=0;repeat<3;++repeat){if(width==0)check(std::abs(energy[repeat][0]-energy[repeat][1])<1e-10,"width zero not centered");else check(energy[repeat][repeat%2]>1e-5&&energy[repeat][1-repeat%2]<energy[repeat][repeat%2]*.001,"echo not alternating");}}
SpaceProcessor p;set(p,"pingpong",1);juce::MemoryBlock saved;p.getStateInformation(saved);SpaceProcessor q;q.setStateInformation(saved.getData(),(int)saved.getSize());check(q.state.getRawParameterValue("pingpong")->load()==1,"ping state lost");q.setCurrentProgram(0);check(q.state.getRawParameterValue("pingpong")->load()==0,"preset reset failed");
auto legacy=p.state.copyState();for(int i=legacy.getNumChildren()-1;i>=0;--i)if(legacy.getChild(i).getProperty("id").toString()=="pingpong")legacy.removeChild(i,nullptr);juce::MemoryBlock old;auto xml=legacy.createXml();juce::AudioProcessor::copyXmlToBinary(*xml,old);set(q,"pingpong",1);q.setStateInformation(old.getData(),(int)old.getSize());check(q.state.getRawParameterValue("pingpong")->load()==0,"legacy state must disable ping");
SpaceProcessor moving;set(moving,"feedback",90);set(moving,"delay",100);set(moving,"spaceOn",0);set(moving,"focus",0);moving.prepareToPlay(48000,256);juce::AudioBuffer<float> block(2,256);juce::MidiBuffer midi;for(int k=0;k<1200;++k){if(k%75==0)set(moving,"pingpong",(k/75)%2);for(int n=0;n<256;++n){float x=.2f*std::sin((k*256+n)*.05f);block.setSample(0,n,x);block.setSample(1,n,x);}moving.processBlock(block,midi);for(int c=0;c<2;++c)for(int n=0;n<256;++n)check(std::isfinite(block.getSample(c,n))&&std::abs(block.getSample(c,n))<3,"unstable automated ping feedback");}
std::cout<<"PASS: L/R/L repeats, centered width 0, untouched direct, 3 rates, saved state, preset reset, legacy state\n";return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
